<?php

declare(strict_types=1);

namespace Primavista\SuluBundle\Tests\HtmlSanitizer;

use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;
use Primavista\SuluBundle\HtmlSanitizer\TextEditorSanitizers;

/**
 * The sanitizer runs on every save, so it must let through exactly what the
 * editor writes. `Fixtures/editor-output.json` is the output of the editor
 * for typical Sulu content, generated by `packages/sulu/test/editorOutput.test.ts`.
 * The comparison ignores the spelling of the markup, see `normalize()`.
 * A Lexical update that changes the output shows up there first.
 */
final class EditorOutputTest extends TestCase
{
    /**
     * @return iterable<string, array{string}>
     */
    public static function editorOutput(): iterable
    {
        $content = \file_get_contents(__DIR__.'/../Fixtures/editor-output.json');
        self::assertNotFalse($content);

        /** @var list<array{name: string, html: string}> $entries */
        $entries = \json_decode($content, true, 512, \JSON_THROW_ON_ERROR);
        foreach ($entries as $entry) {
            yield $entry['name'] => [$entry['html']];
        }
    }

    #[DataProvider('editorOutput')]
    public function testTheSanitizerKeepsWhatTheEditorWrites(string $html): void
    {
        $sanitized = (new TextEditorSanitizers())->get(null)->sanitize($html);

        self::assertSame(self::normalize($html), self::normalize($sanitized));
    }

    /**
     * The sanitizer writes the same content in another spelling: `=` as
     * `&#61;`, `<br>` as `<br />`. Both sides go through one DOM parser, so
     * only a real change of content fails the test: a dropped element or
     * attribute, changed text or changed whitespace.
     */
    private static function normalize(string $html): string
    {
        // libxml knows no custom elements such as sulu-link and warns about them.
        $previous = \libxml_use_internal_errors(true);
        $document = new \DOMDocument();
        $document->loadHTML('<?xml encoding="utf-8"?><body>'.$html.'</body>', \LIBXML_HTML_NOIMPLIED | \LIBXML_HTML_NODEFDTD);
        \libxml_clear_errors();
        \libxml_use_internal_errors($previous);
        $body = $document->getElementsByTagName('body')->item(0);
        self::assertNotNull($body);

        return $document->saveHTML($body) ?: '';
    }
}
